from taf.selenium.gnb.oam.core.robotkeywords.keywords import SeleniumOAMKeywords
from taf.selenium.gnb.oam.core.webdrivers import CustomWebDriverFirefoxMobile, CustomWebDriverChromeMobile
from taf.selenium.mobile.core.devices import CustomDeviceChrome, CustomDeviceFirefox
from taf.selenium.mobile.core.common.download import DownloadChecker
from taf.selenium.mobile.core.exceptions import DeviceNameNotProvided


class core(SeleniumOAMKeywords):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def __init__(self):
        super(SeleniumOAMKeywords, self).__init__()
        self._download_checker = None

    def _create_download_checker(self):
        self._download_checker = DownloadChecker(self._download_dir)

    def create_firefox_web_driver(self, download_dir, name, **kwargs):
        """
        create web driver for mobile firefox

        :param download_dir: path to download directory
        :type download_dir: str
        :param name: the name representing a browser instance
        :type name: str
        :param kwargs: mobile firefox specific parameters:
            str device_name: mobile device name
        :type kwargs: Any

        :return: CustomWebDriverFirefoxMobile instance
        :raises DeviceNameNotProvided: if no device_name provided
        """
        self._create_download_checker()

        device_name = kwargs.get('device_name', None)
        if device_name is None:
            raise DeviceNameNotProvided
        device = CustomDeviceFirefox(device_name)
        driver = CustomWebDriverFirefoxMobile(download_dir=download_dir, device=device)
        driver.set_window_size(device.width, device.height)
        self.set_alias(name, driver)
        return driver

    def create_chrome_web_driver(self, download_dir, name, **kwargs):
        """
        create web driver for mobile chrome

        :param download_dir: path to download directory
        :type download_dir: str
        :param name: the name representing a browser instance
        :type name: str
        :param kwargs: mobile firefox specific parameters:
            str device_name: mobile device name
            Optional[str] preferences_file: chrome preferences file, it contains default emulated devices.
        :type kwargs: Any

        :return: CustomWebDriverChromeMobile instance
        :raises DeviceNameNotProvided: if no device_name provided
        """
        self._create_download_checker()

        device_name = kwargs.get('device_name', None)
        preferences_file = kwargs.get('preferences_file', None)
        if device_name is None:
            raise DeviceNameNotProvided
        device = CustomDeviceChrome(device_name, preferences_file)
        driver = CustomWebDriverChromeMobile(download_dir=download_dir, device=device)
        self.set_alias(name, driver)
        return driver
